class Solution {
public:
    int countPairs(vector<int>& nums, int target) {
        int freq[101] = {0};
        for (int x : nums) freq[x + 50]++;
        int ans = 0;
        for (int a = 0; a < 101; a++) {
            for (int b = a; b < 101; b++) {
                int va = a - 50, vb = b - 50;
                if (va + vb < target) {
                    if (a == b) ans += freq[a] * (freq[a] - 1) / 2;
                    else        ans += freq[a] * freq[b];
                }
            }
        }
        return ans;
    }
};
